CREATE INDEX "vendor_claim_requests_vendor_id_idx" ON "vendor_claim_requests" USING btree ("vendor_id");--> statement-breakpoint
CREATE INDEX "vendor_services_vendor_id_idx" ON "vendor_services" USING btree ("vendor_id");--> statement-breakpoint
CREATE POLICY "vendor_claim_requests_select_own_or_team" ON "vendor_claim_requests" AS PERMISSIVE FOR SELECT TO "authenticated" USING ("vendor_claim_requests"."created_by" = (select auth.uid()) OR public.is_vendor_team_member("vendor_claim_requests"."vendor_id", (select auth.uid())));--> statement-breakpoint
CREATE POLICY "vendor_claim_requests_insert_authenticated" ON "vendor_claim_requests" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK ("vendor_claim_requests"."created_by" = (select auth.uid()));--> statement-breakpoint
CREATE POLICY "vendor_services_select_public" ON "vendor_services" AS PERMISSIVE FOR SELECT TO "anon", "authenticated" USING (true);--> statement-breakpoint
CREATE POLICY "vendor_services_insert_owner_or_manager" ON "vendor_services" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (public.is_vendor_team_member("vendor_services"."vendor_id", (select auth.uid()), ARRAY['owner', 'manager']));--> statement-breakpoint
CREATE POLICY "vendor_services_update_owner_or_manager" ON "vendor_services" AS PERMISSIVE FOR UPDATE TO "authenticated" USING (public.is_vendor_team_member("vendor_services"."vendor_id", (select auth.uid()), ARRAY['owner', 'manager']));--> statement-breakpoint
CREATE POLICY "vendor_services_delete_owner_or_manager" ON "vendor_services" AS PERMISSIVE FOR DELETE TO "authenticated" USING (public.is_vendor_team_member("vendor_services"."vendor_id", (select auth.uid()), ARRAY['owner', 'manager']));--> statement-breakpoint
ALTER POLICY "vendors_select_public_or_own" ON "vendors" TO anon,authenticated USING ("vendors"."verification_status" IN ('verified', 'unclaimed', 'claim_pending') OR "vendors"."created_by" = (select auth.uid()) OR public.is_vendor_team_member("vendors"."id", (select auth.uid())));